from dotenv import load_dotenv
import openai
import json
import re
import os
### 加载环境变量
load_dotenv()
# 定义不同实体下的具备属性
schema = {
    '金融': ['日期', '股票名称', '开盘价', '收盘价', '成交量'],
}
IE_PATTERN = "{}\n\n提取上述句子中{}的实体，并按照JSON格式输出，上述句子中不存在的信息用['原文中未提及']来表示，多个值之间用','分隔。"
# 提供一些例子供模型参考
ie_examples = {
        '金融': [
                    {
                        'content': '2023-01-10，股市震荡。股票古哥-D[EOOE]美股今日开盘价100美元，一度飙升至105美元，随后回落至98美元，最终以102美元收盘，成交量达到520000。',
                        'answers': {
                                        '日期': ['2023-01-10'],
                                        '股票名称': ['古哥-D[EOOE]美股'],
                                        '开盘价': ['100美元'],
                                        '收盘价': ['102美元'],
                                        '成交量': ['520000'],
                            }
                    }
        ]
}

# 2 构建函数，进行prompt设计
def init_prompt(ie_examples):
    '''
    构建实体提取提示词
    :param ie_examples:
    :return:
    '''
    history = [
        {'role': 'system', 'content': "现在你需要帮助我完成信息抽取任务，当我给你一个句子时，你需要帮我抽取出句子中实体信息，并按照JSON的格式输出，上述句子中没有的信息用['原文中未提及']来表示，多个值之间用','分隔。"}
    ]
    for example_cls, examples in ie_examples.items():
        for example in examples:
            history.append({'role': 'user', 'content': IE_PATTERN.format(example['content'], schema[example_cls])})
            history.append({'role':'assistant','content':json.dumps(example['answers'])})
    return  history

def clean_response(response: str):
    """
    后处理模型输出。
    Args:
        response (str): _description_
    """
    if '```json' in response:
        res = re.findall(r'```json(.*?)```', response)
        if len(res) and res[0]:
            response = res[0]
        response.replace('、', ',')
    try:
        return json.loads(response)
    except:
        return response

